import java.util.Scanner;

public class WordWise {
    private String str;

    public WordWise() {
        str = "";
    }

    public void readSent() {
        Scanner sc = new Scanner(System.in);
        System.out.println("Enter a sentence:");
        str = sc.nextLine();
    }

    public void freqVowel() {
        int count = 0;
        String vowels = "AEIOUaeiou";
        for (int i = 0; i < str.length(); i++) {
            if (vowels.indexOf(str.charAt(i)) != -1) {
                count++;
            }
        }
        System.out.println("Total vowels present: " + count);
    }

    public void display() {
        System.out.println("Original Sentence: " + str);
        freqVowel();
    }

    public static void main(String[] args) {
        WordWise obj = new WordWise();
        obj.readSent();
        obj.display();
    }
}
/*
VARIABLE DESCRIPTION TABLE:
Variable Name | Data Type | Purpose
str           | String    | Instance variable storing input sentence
count         | int       | Tally of vowels encountered
vowels        | String    | Constant string containing all vowels
i             | int       | Loop index for sentence traversal
obj           | WordWise  | Object instance created in main method
*/
