import java.util.Scanner;

public class StringSort {
    private String[] names;

    public StringSort() {
        names = new String[10];
    }

    public void input() {
        Scanner sc = new Scanner(System.in);
        System.out.println("Enter 10 student names:");
        for (int i = 0; i < names.length; i++) {
            names[i] = sc.nextLine().trim();
        }
    }

    public void sort() {
        // Selection Sort on String array
        for (int i = 0; i < names.length - 1; i++) {
            int minIdx = i;
            for (int j = i + 1; j < names.length; j++) {
                if (names[j].compareToIgnoreCase(names[minIdx]) < 0) {
                    minIdx = j;
                }
            }
            String temp = names[i];
            names[i] = names[minIdx];
            names[minIdx] = temp;
        }
    }

    public void display() {
        System.out.println("\nAlphabetically Sorted Names:");
        for (int i = 0; i < names.length; i++) {
            System.out.println((i + 1) + ". " + names[i]);
        }
    }

    public static void main(String[] args) {
        StringSort obj = new StringSort();
        obj.input();
        obj.sort();
        obj.display();
    }
}
/*
VARIABLE DESCRIPTION TABLE:
Variable Name | Data Type | Purpose
names         | String[]  | Array holding 10 student names
minIdx        | int       | Index of alphabetically smallest string in unsorted part
temp          | String    | Temporary variable for swap
i             | int       | Outer selection loop counter
j             | int       | Inner loop comparison index
obj           | StringSort| Object created in main method
*/
